answers={('textbook',1):('B','CaCO₃+2HNO₃→Ca(NO₃)₂+CO₂+H₂O; প্রদত্ত বিকল্পে CO₂।'),('textbook',2):('D','NaOH পানিতে দ্রবণীয় ক্ষারক; অন্য তিনটি হাইড্রক্সাইড অদ্রবণীয়/অতি অল্প দ্রবণীয়।'),('textbook',3):('D','কমলালেবুর প্রচলিত প্রধান জৈব এসিড সাইট্রিক এসিড।'),('textbook',4):('C','NH₃ দ্রবণ ক্ষারীয়; MgCO₃ এসিড গ্রহণ করে। উভয়েই উপযুক্ত পরিমাণে H⁺ কমিয়ে pH বাড়ায়। HCl যোগে H⁺ বাড়ে।'),('satt','তালিকা9'):('C','H₂SO₄ প্রচলিত তীব্র খনিজ এসিড; অন্য তিনটি জৈব/কার্বনিক দুর্বল এসিড। দ্বিতীয় প্রোটনের আয়নীভবনকে সব ঘনমাত্রায় সম্পূর্ণ বলা হচ্ছে না।'),('satt','তালিকা6'):('A','Mg(OH)₂ এন্টাসিডের পরিচিত উপাদান; অতিরিক্ত পাকস্থলীর এসিড প্রশমিত করে। এটি ওষুধ গ্রহণের মাত্রা/পরামর্শ নয়।'),('satt','সম্পর্কিত3'):('D','এসিটিক এসিড জলীয় দ্রবণে আংশিক আয়নিত; অন্য বিকল্পগুলো প্রচলিত তীব্র এসিড।'),('satt','অগ্ন্যাশয়'):('D','পাঠ্যবইয়ের সারণিতে অগ্ন্যাশয় রসের প্রতিনিধিত্বমূলক pH8.1। বাস্তব শারীরবৃত্তীয় মান বদলায়; এটি চিকিৎসাগত নির্ণায়ক ধ্রুবক নয়।'),('satt','তালিকা10'):('C','কার্বনিক এসিড দুর্বল; জলীয় দ্রবণে আংশিক আয়নিত হয়।')}
sols=[['NO₂ লালচে-বাদামি গ্যাস।','চুনের পানি Ca(OH)₂-এর দ্রবণ; OH⁻ থাকায়25°C-এ pH7-এর বেশি। দ্রবীভূত CO₂ বা দূষণ পেলে মান বদলাতে পারে।','চিত্রে NH₄Cl ও CaO থেকে পাওয়া X হলো NH₃। জলে NH₃+H₂O⇌NH₄⁺+OH⁻; তাই দ্রবণ লাল লিটমাস নীল করে। তাত্ত্বিক পাঠ্যচিত্র, ঘরে গ্যাস উৎপাদনের নির্দেশ নয়।','NH₃(g)+HCl(g)→NH₄Cl(s)। সূক্ষ্ম কঠিন অ্যামোনিয়াম ক্লোরাইডের সাদা ধোঁয়া হয়। বিষাক্ত/ক্ষয়কারী গ্যাসের সরাসরি সংস্পর্শ অনিরাপদ; এটি পরীক্ষার ধাপ নয়।'],['তেঁতুলের পরিচিত এসিড টারটারিক এসিড।','অপ্রশমিত সালফিউরিক এসিড বর্জ্য জলাশয়ে H⁺ বাড়িয়ে pH কমাতে পারে, প্রায়25°C-এ7-এর নিচে নামতে পারে। সঠিক মান মাপতে হবে; রং থেকে বা সব জলাশয় সম্পর্কে নির্দিষ্ট সংখ্যা বলা যায় না।','অনুমোদিত ETP-তে বর্জ্য আলাদা সংগ্রহ, pHমাপা ও নিয়ন্ত্রিত উপযুক্ত ক্ষারক দিয়ে প্রশমন; যেমন H₂SO₄+Ca(OH)₂→CaSO₄+2H₂O। পরে রং/কঠিন পদার্থসহ অন্যান্য দূষক অপসারণ ও মান যাচাই। জলাশয়ে সরাসরি চুন ছিটানো সমাধান নয়; কোনো মাত্রা এখানে নির্ধারিত নয়।','শুধু অম্লীয় তরল বর্জ্য ফেলা থেকে এসিডবৃষ্টি প্রমাণিত হয় না। কারখানায় সালফারযুক্ত জ্বালানি পোড়ানোর SO₂ এবং উচ্চতাপের দহনে NOx বাতাসে গেলে সম্ভাবনা:2SO₂+O₂→2SO₃; SO₃+H₂O→H₂SO₄। সরল নিট মডেলে4NO₂+O₂+2H₂O→4HNO₃। নির্গমন/বৃষ্টির তথ্য দিয়ে যাচাই করতে হবে।'],['ধনাত্মক আধানবিশিষ্ট আয়নকে ক্যাটায়ন বলে।','আর্দ্রবিশ্লেষণে পানির সঙ্গে বিক্রিয়ায় যৌগের বন্ধন/আয়নের পরিবর্তন ঘটে; যেমন CH₃COO⁻+H₂O⇌CH₃COOH+OH⁻। পানিযোজনে পানি যুক্ত হয়, যেমন CuSO₄+5H₂O→CuSO₄·5H₂O; দুটি ধারণা এক নয়।','খর পানির Ca²⁺/Mg²⁺ সাবানের অ্যানায়নের সঙ্গে অদ্রবণীয় লবণ দেয়। যেমন2C₁₇H₃₅COONa+CaCl₂→(C₁₇H₃₅COO)₂Ca↓+2NaCl। তাই সাবান খরচ হলেও ফেনা কম।','খরতার ধরন পরীক্ষা করে পানি মৃদুকরণ উপযোগী। বাইকার্বনেটের অস্থায়ী খরতা ফুটিয়ে/অধঃক্ষেপ পৃথক করে কমানো যায়; স্থায়ী খরতায় অনুমোদিত মৃদুকরণ/আয়নবিনিময় দরকার। কিছু ডিটারজেন্ট ভালো ফেনা দিলেও Ca/Mg অপসারিত হয়েছে বা পানি পানযোগ্য—এ দাবি নয়।']]
sqsol=['ফরমিক এসিড জলে আংশিক আয়নিত হয়:HCOOH+H₂O⇌H₃O⁺+HCOO⁻। তাই দুর্বল; দুর্বল মানে ঘনমাত্রা কম বা নিরাপদ নয়।','Fe³⁺ জলযুক্ত আয়ন আর্দ্রবিশ্লেষণে H₃O⁺ বাড়ায়, তাই FeCl₃-এর সাধারণ জলীয় দ্রবণ অম্লীয়। সরল পাঠ্য মডেলে FeCl₃+3H₂O⇌Fe(OH)₃+3HCl; বাস্তবে ধাপে ধাপে জলযুক্ত আয়নের সাম্য, সব Fe(OH)₃ অবশ্যই জমে—এ দাবি নয়।','pH12.5 অত্যন্ত ক্ষারীয় মাটির ইঙ্গিত। আগে স্বীকৃত মাটি পরীক্ষায় ক্ষারত্ব, লবণাক্ততা ও সোডিয়ামের অবস্থা নির্ণয়, এরপর কৃষি বিশেষজ্ঞের পরামর্শে সংশোধন। পাঠ্য ধারণায় নিয়ন্ত্রিত অম্ল-উৎপাদক সংশোধনী pH কমাতে পারে; সোডিক মাটিতে জিপসামের ভূমিকা আলাদা। সরাসরি এসিড ঢালা বা অনুমাননির্ভর সারমাত্রা দেওয়া নিরাপদ নয়।']
