for i,k in enumerate([2,3,4,5,6,8,9,10,11,12],1):
 power=f'10^{(-k)}';m=dict(inputs=dict(hExponent=-k,pH=k,temperatureC=25),variant='HYDROGEN_CONCENTRATION_DATA_VARIANT');prefix=f'25°C-এ একটি লঘু জলীয় দ্রবণে [H⁺]={power} mol L⁻¹।'
